-- 2151: the academy teaches and tests what releases 35 and 36 brought (docs/changes/2026-11-11-r35-docs-guides-academy-deck.md):
-- the onboarding gate, the quiz rules, breaks, quiet hours and the townhall for every path; recorded calls, automatic
-- answers and coverage for customer service; rebooking, intent, offers and price limits for Sales; the shift board,
-- delivery and fuel for Fleet; statement periods and payroll for Finance; the shift picker for field staff. Six sections
-- (supabase/seed/academy/r35docs.mjs, generated below), each with its quiz at the 90% pass mark (program_settings).
-- No applied migration is edited. Staff who had passed every section of their path keep a week before the new sections hold
-- them (as 0932 and 1040 did); nothing is reset.
create temp table r35docs_done on commit drop as
select distinct e.user_id from academy_enrollments e where app.academy_done(e.user_id);

-- ACADEMY 2151 START (generated by supabase/seed/2151_gen_academy.mjs from supabase/seed/academy/r35docs.mjs; do not edit by hand)
-- ACADEMY 2151 END

update academy_enrollments e set lock_from = greatest(e.lock_from, now() + interval '7 days')
  from r35docs_done d where e.user_id = d.user_id and e.gate;
