insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-team-rules', 'Onboarding, the academy rules and your shift', 'The four steps before your portal opens, how quizzes are passed, breaks and idle alerts, quiet hours and the weekly townhall.', array['va/your-workday', 'va/academy', 'field/academy', 'admin/people-and-access', 'admin/academy']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-team-rules'), 1, 'Before your portal opens', '[{"caption":"Four steps","say":"A new person opens their portal after four steps, in order: the academy, the staff agreement, the team''s WhatsApp groups, then an approval by an Admin or a Fleet VA.","visual":{"kind":"steps","heading":"In order","items":["Pass the academy","Sign your staff agreement","Confirm the WhatsApp groups","Wait for the approval"]}},{"caption":"A rejection","say":"If the approval is rejected, the person sees the reason, fixes it and asks again.","visual":{"kind":"rule","heading":"Approval","text":"Everyone already working waits for the same approval once.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-team-rules'), 2, 'Passing a quiz', '[{"caption":"90 percent","say":"A quiz passes at 90 percent. The questions come in a random order and open only after the section''s reading time.","visual":{"kind":"title","heading":"Pass mark","text":"90%"}},{"caption":"Tries","say":"After a failed try you wait 30 minutes, and you have 3 tries a day. Answers given too fast are flagged to the Admins.","visual":{"kind":"list","heading":"The rules","items":["90% to pass","30 minutes after a failed try","3 tries a day","Too fast is flagged"]}},{"caption":"New sections","say":"New sections for your role are added to your path. If you had passed everything, you keep a week before they hold you, and nothing you passed is reset.","visual":{"kind":"rule","heading":"Nothing reset","text":"Only the new sections are left to do.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-team-rules'), 3, 'Your shift', '[{"caption":"Breaks","say":"Log a break from your home page when you step away, and end it when you are back. The idle alert is paused while you are on a break, on a call or in the townhall.","visual":{"kind":"chat","lines":[{"who":"you","text":"Starting my break."},{"who":"app","text":"Break started. Idle alerts are paused until you end it."}]}},{"caption":"Quiet hours","say":"Alerts held by your quiet hours arrive as one summary when they end. Renters get no automatic text at night; an answer asked for then arrives in the morning.","visual":{"kind":"rule","heading":"No night texts","text":"Automatic texts wait for the morning.","tone":"ok"}},{"caption":"The townhall","say":"The townhall is every Wednesday at 1:00 pm Toronto time. Two missed in a row lock your account until an Admin restores it.","visual":{"kind":"rule","heading":"Two misses lock","text":"Join through the link and confirm you are in the call.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-team-rules'), 1, 'What is the pass mark of an academy quiz?', '["70%","80%","90%","100%"]'::jsonb, 2, 'A quiz passes at 90%.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-team-rules'), 2, 'You failed a quiz. When can you try again?', '["At once","After 30 minutes","Tomorrow only","After an Admin resets it"]'::jsonb, 1, 'After a failed try you wait 30 minutes.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-team-rules'), 3, 'How many tries of a quiz do you have a day?', '["1","3","5","No limit"]'::jsonb, 1, 'Three tries a day.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-team-rules'), 4, 'What is the last onboarding step before the portal opens?', '["The academy","The staff agreement","An approval by an Admin or a Fleet VA","The WhatsApp groups"]'::jsonb, 2, 'The fourth step is the approval.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-team-rules'), 5, 'When is the idle alert paused?', '["Never","On a break, on a call or in the townhall","Only at night","When you close the tab"]'::jsonb, 1, 'Breaks, calls and the townhall pause it.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-team-rules'), 6, 'What happens after two missed townhalls in a row?', '["Nothing","A warning email only","The account locks until an Admin restores it","Your pay is cut"]'::jsonb, 2, 'Two misses in a row lock the account.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
