insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-cs-calls-answers', 'Recorded calls, automatic answers and coverage', 'Calls are recorded with a transcript, automatic answers handle common questions, and coverage is checked against the car.', array['va/customer-service', 'admin/texts-and-calls-the-quo-phone-line', 'admin/settings']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-cs-calls-answers'), 1, 'Calls and answers', '[{"caption":"Recorded calls","say":"Calls from the Call button are recorded. The transcript, a summary and Play recording show on the renter''s, lead''s and booking''s history.","visual":{"kind":"title","heading":"Call history","text":"Transcript, summary, recording"}},{"caption":"Automatic answers","say":"Common questions on text, email, chat and social messages are answered at once from our FAQ. A question it cannot answer becomes your To do.","visual":{"kind":"chat","lines":[{"who":"renter","text":"Do you deliver to the airport?"},{"who":"app","text":"Answered from the FAQ."},{"who":"renter","text":"Can I return the car in Ottawa?"},{"who":"app","text":"To do for customer service."}]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-cs-calls-answers'), 2, 'Coverage and the trip', '[{"caption":"Card coverage","say":"The renter picks their card and the page checks it against the car. A card that does not cover the car cannot be approved.","visual":{"kind":"rule","heading":"Not covered","text":"Offer OPCF 27 or the Protection Plan.","tone":"warn"}},{"caption":"OPCF 27","say":"Approve OPCF 27 only with both the pink slip and the endorsement page.","visual":{"kind":"list","heading":"Both pages","items":["The pink slip","The endorsement page"]}},{"caption":"Rideshare and the trip","say":"Rideshare and delivery work is allowed with the documents the renter makes on their booking. The secondary contact is on the booking, and the mid-trip message asks how it is going; a problem becomes your To do.","visual":{"kind":"rule","heading":"Allowed","text":"Rideshare and delivery are allowed with the documents.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-cs-calls-answers'), 1, 'Where do you find a recorded call''s transcript?', '["Nowhere, calls are not recorded","On the renter''s, lead''s and booking''s history","Only in Twilio","In an email to the Admin"]'::jsonb, 1, 'The transcript and summary are on the history.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-cs-calls-answers'), 2, 'An automatic answer cannot reply to a question. What happens?', '["The renter gets nothing","It becomes a To do for a person","The chat closes","It answers anyway"]'::jsonb, 1, 'A question it cannot answer becomes a To do.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-cs-calls-answers'), 3, 'What do you need to approve OPCF 27?', '["The pink slip only","The endorsement page only","Both the pink slip and the endorsement page","A selfie"]'::jsonb, 2, 'Both pages are required.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-cs-calls-answers'), 4, 'A renter wants to drive for Uber. What do you say?', '["It is not allowed","It is allowed with the documents from their booking page","Only with an Admin''s signature","Only on weekends"]'::jsonb, 1, 'Rideshare and delivery are allowed with the documents.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-cs-calls-answers'), 5, 'The card the renter picked does not cover the car. What do you do?', '["Approve it anyway","Offer OPCF 27 or the Protection Plan","Cancel the booking","Ignore it"]'::jsonb, 1, 'A card that does not cover the car cannot be approved.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'cs', (select id from academy_sections where slug = 'new-r35-cs-calls-answers'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'cs' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'admin', (select id from academy_sections where slug = 'new-r35-cs-calls-answers'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'admin' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-sales-rebook-intent', 'Rebooking, intent and offers in three steps', 'Returning renters come back to you, every lead has an intent score, offers are three steps with their history, prices stay within the owner''s limits.', array['va/sales', 'admin/leads-and-sales-claims', 'admin/requests-offers-and-bookings']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-sales-rebook-intent'), 1, 'Who gets the lead', '[{"caption":"Rebooking","say":"A returning renter''s new request goes straight to the salesperson of their last booking, with the usual claim time.","visual":{"kind":"rule","heading":"Your renters come back to you","text":"Answer within the claim time or it goes back to the pool.","tone":"ok"}},{"caption":"Intent","say":"Each lead has an intent score, hot, warm or cold, with what they said they want, read from calls and their transcripts, texts, emails, chat and visits.","visual":{"kind":"list","heading":"Intent reads","items":["Budget and car class","Length and dates","Urgency","Delivery and coverage"]}},{"caption":"Hot first","say":"Call the hot leads first.","visual":{"kind":"title","heading":"Hot, warm, cold","text":"Hot first"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-sales-rebook-intent'), 2, 'Offers and prices', '[{"caption":"Three steps","say":"An offer is three steps: car and dates, price, review and send. Every version is kept, and an old one can be loaded as a new offer.","visual":{"kind":"steps","heading":"Send an offer","items":["Car and dates","Price","Review and send"]}},{"caption":"Price limits","say":"Prices stay between the owner''s daily minimum and maximum. Only an Admin allows one request outside them, with a reason.","visual":{"kind":"rule","heading":"Owner limits","text":"You cannot go below the owner''s minimum.","tone":"warn"}},{"caption":"Instant and rewards","say":"A verified repeat renter can book an available car instantly. Renters earn points for a photo with their review and for every rental after the first.","visual":{"kind":"money","heading":"Rewards","rows":[["Photo with a review","points"],["Every rental after the first","points"]]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-sales-rebook-intent'), 1, 'A renter you served books again. Who gets their request?', '["The next salesperson in line","You, the salesperson of their last booking","An Admin","Customer service"]'::jsonb, 1, 'It goes to the salesperson of their last booking.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-sales-rebook-intent'), 2, 'Which lead do you call first?', '["The oldest cold lead","A hot lead","Any warm lead","None until asked"]'::jsonb, 1, 'Hot leads first.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-sales-rebook-intent'), 3, 'What are the three steps of an offer?', '["Price, pay, sign","Car and dates, price, review and send","Request, approve, cancel","Call, text, email"]'::jsonb, 1, 'Car and dates, price, review and send.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-sales-rebook-intent'), 4, 'The renter wants a price under the owner''s minimum. What do you do?', '["Send it anyway","Ask an Admin, who may allow it with a reason","Use a promo code to go under","Change the car''s rate"]'::jsonb, 1, 'Only an Admin allows one outside the limits.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-sales-rebook-intent'), 5, 'Who can book instantly?', '["Anyone","A verified repeat renter, on an available car","Only Admins","Owners only"]'::jsonb, 1, 'Verified repeat renters book available cars instantly.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'sales_in_person', (select id from academy_sections where slug = 'new-r35-sales-rebook-intent'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'sales_in_person' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'sales_remote', (select id from academy_sections where slug = 'new-r35-sales-rebook-intent'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'sales_remote' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'admin', (select id from academy_sections where slug = 'new-r35-sales-rebook-intent'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'admin' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-fleet-shifts-delivery', 'The shift board, delivery and fuel', 'Availability and standing shifts on the board, unclaimed shift alerts, approving new staff, delivery by distance and the fuel suggestion.', array['va/fleet', 'admin/people-and-access', 'admin/requests-offers-and-bookings']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-fleet-shifts-delivery'), 1, 'Shifts', '[{"caption":"The board","say":"The shift board shows each field person''s availability, the standing weekly shifts, who is under the minimum and the people to ask for each slot.","visual":{"kind":"list","heading":"On the board","items":["Availability","Standing shifts","Under the minimum","People to ask"]}},{"caption":"Unclaimed","say":"A published shift nobody has claimed 48 hours before it starts alerts Fleet and the Admins with the people to ask.","visual":{"kind":"rule","heading":"48 hours","text":"Ask the people suggested for the slot.","tone":"warn"}},{"caption":"Approvals","say":"Fleet VAs can approve a new person at the fourth onboarding step, or reject with a reason they see.","visual":{"kind":"steps","heading":"Approve","items":["Open the person","Check the first three steps","Approve or reject with a reason"]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-fleet-shifts-delivery'), 2, 'Delivery and fuel', '[{"caption":"Delivery by distance","say":"Delivery is priced by distance from 1570 Midland Ave: a base, the kilometres included and a rate per km, all in Program settings.","visual":{"kind":"title","heading":"From the office","text":"Base, km included, per km"}},{"caption":"Fuel","say":"The fuel line at the return is a suggestion from the car''s tank, the weekly pump price and a multiplier, plus the refuelling fee. You check it on the deposit review; nothing is charged by itself.","visual":{"kind":"rule","heading":"Check first","text":"Fuel is never charged without a check.","tone":"ok"}},{"caption":"Test cars","say":"An Admin can delete a car that has only test bookings. A car with a real booking cannot be deleted.","visual":{"kind":"rule","heading":"Real bookings stay","text":"Only cars with test bookings only can go.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-shifts-delivery'), 1, 'A shift has no one 48 hours before it starts. What happens?', '["Nothing","Fleet and the Admins are alerted with the people to ask","It is deleted","It is given to a random person"]'::jsonb, 1, 'An unclaimed shift alerts Fleet and the Admins.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-shifts-delivery'), 2, 'Where is delivery measured from?', '["The renter''s home","1570 Midland Ave","The airport","The owner''s address"]'::jsonb, 1, 'Delivery is priced by distance from the company''s address.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-shifts-delivery'), 3, 'Is the fuel line at the return charged by itself?', '["Yes, at once","No, it is a suggestion checked on the deposit review","Only on weekends","Only for electric cars"]'::jsonb, 1, 'It is a suggestion to check.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-shifts-delivery'), 4, 'Who can approve a new person at the last onboarding step?', '["Anyone","An Admin or a Fleet VA","The new person","Sales"]'::jsonb, 1, 'An Admin or a Fleet VA approves.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-fleet-shifts-delivery'), 5, 'Which car can be deleted?', '["Any car","A car with only test bookings","A car on rent","A car with a past real booking"]'::jsonb, 1, 'Only a car whose bookings are all tests.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_path_sections (path_code, section_id, sort) select 'fleet', (select id from academy_sections where slug = 'new-r35-fleet-shifts-delivery'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'fleet' on conflict (path_code, section_id) do nothing;
insert into academy_path_sections (path_code, section_id, sort) select 'admin', (select id from academy_sections where slug = 'new-r35-fleet-shifts-delivery'), coalesce(max(sort), 0) + 1 from academy_path_sections where path_code = 'admin' on conflict (path_code, section_id) do nothing;
insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-finance-statements-payroll', 'Statement periods and payroll', 'Statements run from the 8th to the 7th with uncollected amounts apart, and payroll every two weeks goes through an Admin''s approval.', array['va/finance', 'admin/owner-money']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-finance-statements-payroll'), 1, 'Statements', '[{"caption":"8th to 7th","say":"Each owner statement covers the 8th of one month to the 7th of the next, paid on the 10th. A rental across the cutoff is paid for its days in each period, never twice.","visual":{"kind":"money","heading":"A period","rows":[["From","the 8th"],["To","the 7th"],["Payout","the 10th"]]}},{"caption":"Uncollected","say":"Amounts not yet collected from the renter are listed apart and paid on the statement after they come in.","visual":{"kind":"rule","heading":"Paid once collected","text":"Never pay an owner money we have not collected.","tone":"warn"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-finance-statements-payroll'), 2, 'Payroll', '[{"caption":"Every two weeks","say":"Prepare the run with any bonus or deduction and its reason, then send it for approval. An Admin approves and records the payments. Nothing is paid by itself.","visual":{"kind":"steps","heading":"A payroll run","items":["Start it after the period ends","Add bonuses or deductions with a reason","Send for approval","An Admin approves and records"]}},{"caption":"Email capacity","say":"Settings, Usage shows the real daily capacity of all our sending services together. Receipts, signed copies and staff messages always go.","visual":{"kind":"title","heading":"Usage","text":"Real daily capacity"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-finance-statements-payroll'), 1, 'What does an owner statement cover?', '["The 1st to the 30th","The 8th of one month to the 7th of the next","Two weeks","Each rental alone"]'::jsonb, 1, 'The 8th to the 7th, paid on the 10th.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
insert into academy_questions (section_id, sort, prompt, options, answer, explain) values ((select id from academy_sections where slug = 'new-r35-finance-statements-payroll'), 2, 'A renter has not paid a charge yet. What happens on the owner''s statement?', '["It is paid to the owner anyway","It is listed apart and paid once collected","It is deleted","The owner pays it"]'::jsonb, 1, 'Uncollected amounts are paid on the statement after they come in.') on conflict (section_id, sort) do update set prompt = excluded.prompt, options = excluded.options, answer = excluded.answer, explain = excluded.explain, updated_at = now();
