insert into academy_sections (slug, title, blurb, guide_refs) values ('new-r35-field-shift-picker', 'Availability, standing shifts and the minimum', 'Set when you can work, claim shifts from the week calendar, keep a standing weekly shift and hold the minimum.', array['field/my-hours-and-pay']::text[]) on conflict (slug) do update set title = excluded.title, blurb = excluded.blurb, guide_refs = excluded.guide_refs, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-field-shift-picker'), 1, 'Your shifts', '[{"caption":"Availability","say":"Set when you can work, mornings, afternoons and evenings for each weekday, on Welcome. Change it later on My shifts or Profile.","visual":{"kind":"list","heading":"Availability","items":["Mornings","Afternoons","Evenings","A note"]}},{"caption":"Week calendar","say":"My shifts opens as a week calendar. Tap a shift to claim it. The cards are on the List tab.","visual":{"kind":"steps","heading":"Claim a shift","items":["Open My shifts","Tap the shift","Claim it"]}},{"caption":"Standing shifts","say":"A standing weekly shift, such as every Saturday 10 to 6, claims each matching published shift by itself up to two weeks ahead. Drop one date or end it; the give-up rules apply.","visual":{"kind":"rule","heading":"Two weeks ahead","text":"Standing shifts claim while the shift has room.","tone":"ok"}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
insert into academy_lessons (section_id, sort, title, scenes) values ((select id from academy_sections where slug = 'new-r35-field-shift-picker'), 2, 'The minimum and pay', '[{"caption":"The minimum","say":"Hold at least the minimum, 2 shifts in 7 days by default. Under it, you get a daily reminder and a To do.","visual":{"kind":"title","heading":"Minimum","text":"2 shifts in 7 days"}},{"caption":"Pay","say":"Pay stubs come every two weeks under My pay, with a PDF and an email once paid.","visual":{"kind":"money","heading":"My pay","rows":[["Hours","every two weeks"],["Stub","PDF and email"]]}}]'::jsonb) on conflict (section_id, sort) do update set title = excluded.title, scenes = excluded.scenes, updated_at = now();
